import os
import sys
import time
import json
import hmac
import hashlib
import tempfile
import struct
import fcntl
from pathlib import Path
from typing import Optional, Dict, Any

# Configuration
SESSION_DIR = '/var/lib/app/sessions'
SECRET_KEY = os.urandom(32)
MAX_SESSION_AGE = 3600
MAX_SESSION_SIZE = 8192

def constant_time_eq(a: bytes, b: bytes) -> bool:
    """Timing-safe comparison."""
    return hmac.compare_digest(a, b)

def compute_session_mac(session_id: str, data: bytes) -> bytes:
    """Compute HMAC-SHA256 for session integrity."""
    return hmac.new(SECRET_KEY, session_id.encode() + data, hashlib.sha256).digest()

def validate_session_id(session_id: str) -> bool:
    """Validate session ID format - alphanumeric only, fixed length."""
    if not session_id or len(session_id) != 32:
        return False
    return all(c in '0123456789abcdef' for c in session_id)

def get_session_path(session_id: str) -> str:
    """Get the filesystem path for a session file."""
    if not validate_session_id(session_id):
        raise ValueError("Invalid session ID")
    return os.path.join(SESSION_DIR, f'sess_{session_id}')

def read_session(session_id: str) -> Optional[Dict[str, Any]]:
    """Read and verify a session from disk."""
    if not validate_session_id(session_id):
        return None

    session_path = get_session_path(session_id)

    try:
        # Check file exists and is a regular file
        stat_result = os.stat(session_path)
        if not stat_result.st_mode & 0o100000:  # S_ISREG
            return None
        if stat_result.st_size > MAX_SESSION_SIZE:
            return None

        with open(session_path, 'rb') as f:
            fcntl.flock(f.fileno(), fcntl.LOCK_SH)
            raw = f.read(MAX_SESSION_SIZE)
            fcntl.flock(f.fileno(), fcntl.LOCK_UN)

        if len(raw) < 32:
            return None

        stored_mac = raw[:32]
        payload = raw[32:]

        expected_mac = compute_session_mac(session_id, payload)
        if not constant_time_eq(stored_mac, expected_mac):
            return None

        session_data = json.loads(payload)

        if time.time() - session_data.get('_created', 0) > MAX_SESSION_AGE:
            delete_session(session_id)
            return None

        return session_data
    except (OSError, json.JSONDecodeError, ValueError):
        return None

def write_session(session_id: str, data: Dict[str, Any]) -> bool:
    """Write session data atomically to disk."""
    if not validate_session_id(session_id):
        return False

    session_path = get_session_path(session_id)
    data['_created'] = data.get('_created', time.time())
    data['_updated'] = time.time()

    payload = json.dumps(data, separators=(',', ':')).encode('utf-8')
    if len(payload) > MAX_SESSION_SIZE - 32:
        return False

    mac = compute_session_mac(session_id, payload)
    content = mac + payload

    try:
        # Atomic write: write to temp file then rename
        dir_path = os.path.dirname(session_path)

        # Create temp file in same directory for atomic rename
        fd, tmp_path = tempfile.mkstemp(dir=dir_path, prefix='.tmp_sess_')
        try:
            os.write(fd, content)
            os.fsync(fd)
            os.close(fd)
            fd = -1

            # Set restrictive permissions
            os.chmod(tmp_path, 0o600)

            # Atomic rename to final path
            os.rename(tmp_path, session_path)
            return True
        except:
            if fd >= 0:
                os.close(fd)
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)
            raise
    except OSError:
        return False

def delete_session(session_id: str) -> bool:
    """Delete a session file."""
    if not validate_session_id(session_id):
        return False
    try:
        os.unlink(get_session_path(session_id))
        return True
    except OSError:
        return False

def elevate_session_privileges(session_id: str, target_role: str) -> bool:
    """Elevate session to a new role after re-authentication."""
    session = read_session(session_id)
    if session is None:
        return False

    # Verify the session is still valid by checking the file hasn't been tampered
    session_path = get_session_path(session_id)

    # Re-read to ensure consistency (double-check pattern)
    try:
        file_stat = os.lstat(session_path)
        if file_stat.st_nlink != 1:
            return False  # Hardlink attack detection
        if file_stat.st_uid != os.getuid():
            return False  # Ownership check
    except OSError:
        return False

    # TOCTOU window: between lstat above and write below,
    # the file could be replaced with a symlink
    session['role'] = target_role
    session['_elevated'] = time.time()

    return write_session(session_id, session)

def cleanup_expired_sessions() -> int:
    """Remove expired session files."""
    removed = 0
    try:
        for entry in os.scandir(SESSION_DIR):
            if not entry.name.startswith('sess_'):
                continue
            if not entry.is_file(follow_symlinks=False):
                continue
            try:
                if time.time() - entry.stat().st_mtime > MAX_SESSION_AGE:
                    os.unlink(entry.path)
                    removed += 1
            except OSError:
                continue
    except OSError:
        pass
    return removed

# HTTP request handler (simplified WSGI-like interface)
def handle_request(environ: Dict[str, str]) -> tuple:
    """Process an incoming HTTP request."""
    method = environ.get('REQUEST_METHOD', 'GET')
    path = environ.get('PATH_INFO', '/')

    # Extract session cookie
    cookie_header = environ.get('HTTP_COOKIE', '')
    session_id = None
    for part in cookie_header.split(';'):
        part = part.strip()
        if part.startswith('sid='):
            session_id = part[4:]
            break

    if path == '/api/session' and method == 'POST':
        # Create new session
        new_id = os.urandom(16).hex()
        session_data = {'user': environ.get('REMOTE_USER', 'anonymous'), 'role': 'user'}
        if write_session(new_id, session_data):
            return ('200', json.dumps({'session_id': new_id}), f'Set-Cookie: sid={new_id}; HttpOnly; Secure; SameSite=Strict')
        return ('500', '{"error":"session creation failed"}', '')

    elif path == '/api/session/elevate' and method == 'POST':
        if not session_id or not validate_session_id(session_id):
            return ('401', '{"error":"no session"}', '')
        # In production, re-authentication would happen here
        if elevate_session_privileges(session_id, 'admin'):
            return ('200', '{"status":"elevated"}', '')
        return ('403', '{"error":"elevation failed"}', '')

    elif path == '/api/profile' and method == 'GET':
        if not session_id:
            return ('401', '{"error":"unauthorized"}', '')
        session = read_session(session_id)
        if not session:
            return ('401', '{"error":"invalid session"}', '')
        return ('200', json.dumps({'user': session.get('user'), 'role': session.get('role')}), '')

    elif path == '/api/admin/cleanup' and method == 'POST':
        if not session_id:
            return ('401', '{"error":"unauthorized"}', '')
        session = read_session(session_id)
        if not session or session.get('role') != 'admin':
            return ('403', '{"error":"forbidden"}', '')
        count = cleanup_expired_sessions()
        return ('200', json.dumps({'removed': count}), '')

    return ('404', '{"error":"not found"}', '')
